        "content": "**Генотерапия** — учебный раздел, связанный с методичкой «Генетика 2. Генетика человека». В медицинской генетике эта тема важна потому, что помогает связывать молекулярный механизм, тип наследования и клинический фенотип пациента. При разборе всегда нужно различать генотип, фенотип, вероятность передачи признака и ограничения конкретной модели.\n\nКлючевая идея раздела: генотерапия рассматривается не как изолированный термин, а как часть диагностического мышления. Например, при анализе семьи студент сопоставляет родословную, лабораторные данные, симптомы и известные закономерности наследования. Такая логика помогает отличить моногенное заболевание от хромосомной патологии, многофакторной предрасположенности или фенокопии.\n\nПрактически полезно запомнить несколько шагов: 1) определить объект анализа; 2) записать возможные генотипы; 3) указать механизм проявления признака; 4) оценить риск для родственников; 5) выбрать метод подтверждения — цитогенетический, биохимический или молекулярно-генетический. Ошибки чаще возникают, когда фенотип сразу приравнивают к генотипу без учёта пенетрантности, экспрессивности и влияния среды.\n\n**Пример.** Если тема связана с наследованием, удобно построить решётку Пеннета или схему родословной. Если тема связана с заболеванием, важно указать тип мутации, поражаемую систему органов, возраст манифестации, доступные методы диагностики и подходы к наблюдению.",
